MESSAGE = "Meet me at the CodeItAll cafe at noon!"
SHIFT = 7

def caesar(text, shift):
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + shift) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + shift) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

secret = caesar(MESSAGE, SHIFT)
print("Plain :", MESSAGE)
print("Secret:", secret)
(OUTPUT_DIR / "cipher_secret.txt").write_text(secret, encoding="utf-8")

