PROMPTS = [
    "python loves clean loops",
    "codeitall makes learning playful",
    "functions are reusable spells",
]
SECONDS = [4.2, 5.1, 3.8]  # pretend you typed each prompt in this many seconds

def wpm(text, seconds):
    words = len(text.split())
    return words / (seconds / 60)

attempts = []
for text, sec in zip(PROMPTS, SECONDS):
    attempts.append({"text": text, "seconds": sec, "wpm": wpm(text, sec), "chars": len(text)})
for a in attempts:
    print(f"{a['wpm']:.1f} WPM in {a['seconds']}s — {a['text']}")

