import numpy as np

# 🎛️ TWEAK THESE
BPM = 96
BARS = 2
SR = 22050
KICK_PAT = "x---x---x---x---"
HAT_PAT = "x-x-x-x-x-x-x-x-"

def env_noise(n, decay=0.001):
    t = np.arange(n) / SR
    return (np.random.randn(n) * np.exp(-t / decay)).astype(np.float64)

def kick(n):
    t = np.arange(n) / SR
    freq = np.linspace(140, 40, n)
    return 0.9 * np.sin(2 * np.pi * freq * t) * np.exp(-t * 8)

step = int(SR * 60 / BPM / 4)
total = step * 16 * BARS
mix = np.zeros(total)
rng = np.random.default_rng(0)

def stamp(pattern, sound_fn, gain=1.0):
    for bar in range(BARS):
        for i, ch in enumerate(pattern):
            if ch.lower() == "x":
                pos = (bar * 16 + i) * step
                burst = sound_fn(step)
                end = min(pos + len(burst), total)
                mix[pos:end] += gain * burst[: end - pos]

stamp(KICK_PAT, kick, 0.9)
stamp(HAT_PAT, lambda n: env_noise(n, 0.004), 0.25)
mix = mix / max(1e-9, np.max(np.abs(mix)))
print("Audio samples:", len(mix), "duration sec:", len(mix) / SR)
